    fun build(type: String, cx: Float, cy: Float, size: Float): Path? {
        val contours = data[type.lowercase()] ?: return null
        val path = Path().apply { fillType = Path.FillType.EVEN_ODD }
        contours.forEach { pts ->
            if (pts.size < 6) return@forEach
            path.moveTo(cx + pts[0] * size, cy + pts[1] * size)
            var i = 2
            while (i + 1 < pts.size) {
                path.lineTo(cx + pts[i] * size, cy + pts[i + 1] * size)
                i += 2
            }
            path.close()
        }
        return path
    }
